// Lead Spanish review 2026-10-19 (LEAD-SPANISH-REVIEW-LOG-v1.json): NY08 catalog entries; ES only, English unchanged.
export const LEAD_SPANISH_SUCCESSORS_20261019=[{"index":551,"before":{"id":"NY16055-SOURCE-BOUNDARY","originalEnglish":"A prior interests-of-justice non-sealing order requires motion or lawyer review. A disposition before November 1, 1991 may require the statute's legacy motion procedure. Exact record dates and source verification remain separate; this screening does not decide those facts.","kind":"result_reason","en":"A prior interests-of-justice non-sealing order requires motion or lawyer review. A disposition before November 1, 1991 may require the statute's legacy motion procedure. Exact record dates and source verification remain separate; this screening does not decide those facts.","es":"Una orden anterior de no sellar en interés de la justicia requiere revisar una moción o consultar a un abogado. Una resolución anterior al 1 de noviembre de 1991 puede requerir el procedimiento de moción anterior previsto en la ley. Las fechas exactas del expediente y la verificación de las fuentes siguen siendo asuntos separados; esta revisión inicial no decide esos hechos.","reviewStatus":"ENGINEERING_COPY_EXISTING_NY08_QUALIFIED_FINISHED_VERSION_REVIEW_PENDING","adoptedEnglishBasis":"NATIONAL-2026-08-28-C-NY-01;ny_160_55_violation"},"after":{"id":"NY16055-SOURCE-BOUNDARY","originalEnglish":"A prior interests-of-justice non-sealing order requires motion or lawyer review. A disposition before November 1, 1991 may require the statute's legacy motion procedure. Exact record dates and source verification remain separate; this screening does not decide those facts.","kind":"result_reason","en":"A prior interests-of-justice non-sealing order requires motion or lawyer review. A disposition before November 1, 1991 may require the statute's legacy motion procedure. Exact record dates and source verification remain separate; this screening does not decide those facts.","es":"Una orden anterior de no sellar en interés de la justicia requiere una moción o la revisión de un abogado. Una resolución anterior al 1 de noviembre de 1991 puede requerir el procedimiento por moción que la ley prevé para esas resoluciones anteriores. Las fechas exactas del expediente y la verificación de las fuentes siguen siendo asuntos separados; esta revisión inicial no decide esos hechos.","reviewStatus":"ENGINEERING_COPY_EXISTING_NY08_QUALIFIED_FINISHED_VERSION_REVIEW_PENDING","adoptedEnglishBasis":"NATIONAL-2026-08-28-C-NY-01;ny_160_55_violation"}},{"index":582,"before":{"id":"NY16057-timing","kind":"result_reason","originalEnglish":"For a misdemeanor, the period is three years from release from incarceration, or sentencing if there was no incarceration. For a felony, it is eight years from the last release from incarceration for the sentence of the conviction to be sealed, or sentencing if there was no incarceration. A later conviction before sealing can re-anchor the earlier clock to the later conviction's start date. These answers do not calculate a date or establish that a waiting period has run.","en":"For a misdemeanor, the period is three years from release from incarceration, or sentencing if there was no incarceration. For a felony, it is eight years from the last release from incarceration for the sentence of the conviction to be sealed, or sentencing if there was no incarceration. A later conviction before sealing can re-anchor the earlier clock to the later conviction's start date. These answers do not calculate a date or establish that a waiting period has run.","es":"Para un delito menor, el plazo es de tres años desde la salida del encarcelamiento, o desde la imposición de la sentencia si no hubo encarcelamiento. Para un delito grave, es de ocho años desde la última salida del encarcelamiento correspondiente a la sentencia de la condena cuyo sellado se considera, o desde la imposición de la sentencia si no hubo encarcelamiento. Una condena posterior antes del sellado puede fijar un nuevo inicio para el plazo anterior en la fecha de inicio del plazo de la condena posterior. Estas respuestas no calculan una fecha ni establecen que haya transcurrido un plazo de espera.","reviewStatus":"ENGINEERING_IMPLEMENTATION_EXISTING_NY08_QUALIFIED_FINISHED_VERSION_REVIEW_PENDING","adoptedEnglishBasis":"NY.memo:ny_clean_slate_convictions;CPL160.57(1)(b);retained-factory:69b215d3673600b18ead7422699eb4e6636de6fe/ad784de7e6ce6f50aee837e9fbdce50eaf37285be74107ecda139b49123780a9"},"after":{"id":"NY16057-timing","kind":"result_reason","originalEnglish":"For a misdemeanor, the period is three years from release from incarceration, or sentencing if there was no incarceration. For a felony, it is eight years from the last release from incarceration for the sentence of the conviction to be sealed, or sentencing if there was no incarceration. A later conviction before sealing can re-anchor the earlier clock to the later conviction's start date. These answers do not calculate a date or establish that a waiting period has run.","en":"For a misdemeanor, the period is three years from release from incarceration, or sentencing if there was no incarceration. For a felony, it is eight years from the last release from incarceration for the sentence of the conviction to be sealed, or sentencing if there was no incarceration. A later conviction before sealing can re-anchor the earlier clock to the later conviction's start date. These answers do not calculate a date or establish that a waiting period has run.","es":"Para un delito menor, el plazo es de tres años desde la salida del encarcelamiento, o desde la imposición de la sentencia si no hubo encarcelamiento. Para un delito grave, es de ocho años desde la última salida del encarcelamiento correspondiente a la sentencia de la condena cuyo sellado se considera, o desde la imposición de la sentencia si no hubo encarcelamiento. Una condena posterior, antes del sellado, puede hacer que el plazo de la condena anterior vuelva a contarse desde la fecha de inicio del plazo de la condena posterior. Estas respuestas no calculan una fecha ni establecen que haya transcurrido un plazo de espera.","reviewStatus":"ENGINEERING_IMPLEMENTATION_EXISTING_NY08_QUALIFIED_FINISHED_VERSION_REVIEW_PENDING","adoptedEnglishBasis":"NY.memo:ny_clean_slate_convictions;CPL160.57(1)(b);retained-factory:69b215d3673600b18ead7422699eb4e6636de6fe/ad784de7e6ce6f50aee837e9fbdce50eaf37285be74107ecda139b49123780a9"}}];

export function leadSpanishCopyPredecessorView(current){
 const predecessor=structuredClone(current);
 for(const change of LEAD_SPANISH_SUCCESSORS_20261019){
  assert.equal(current.entries.filter(entry=>entry.id===change.after.id).length,1,'Unique lead Spanish successor '+change.after.id);
  assert.deepEqual(current.entries[change.index],change.after,'Exact lead Spanish successor '+change.after.id);
  predecessor.entries[change.index]=structuredClone(change.before);
 }
 return predecessor;
}

