export function leadSpanishLayer2PredecessorView(current){
 const predecessor=structuredClone(current);
 for(const change of LEAD_SPANISH_SUCCESSORS_20261019_L2){
  assert.equal(current.entries.filter(entry=>entry.id===change.after.id).length,1,'Unique lead Spanish layer-2 successor '+change.after.id);
  assert.deepEqual(current.entries[change.index],change.after,'Exact lead Spanish layer-2 successor '+change.after.id);
  predecessor.entries[change.index]=structuredClone(change.before);
 }
 return predecessor;
}

export function msAdoptedCopyPredecessorView(current){
 current=leadSpanishLayer2PredecessorView(current);
 current=leadSpanishCopyPredecessorView(current);
 current=msFinalSpanishCopyPredecessorView(current);
 const predecessor=structuredClone(current);
 // Restore only exact three currentNY objects before the retained CA2/MS9 inverse.
 for(const change of NY16055_TERMINOLOGY_SUCCESSORS){
  assert.equal(current.entries.filter(entry=>entry.id===change.after.id).length,1,'Unique declared NY terminology '+change.after.id);
  assert.deepEqual(current.entries[change.index],change.after,'Exact current NY terminology/index '+change.after.id);
  predecessor.entries[change.index]=structuredClone(change.before);
 }

 // Restore only the exact two CA entries before the original MS inverse.
 for(const change of CA_TWO_RESULT_COPY_SUCCESSORS){
  assert.equal(current.entries.filter(entry=>entry.id===change.after.id).length,1,'Unique declared CA successor '+change.after.id);
  assert.deepEqual(current.entries[change.index],change.after,'Exact current CA successor/index '+change.after.id);
  predecessor.entries[change.index]=structuredClone(change.before);
 }
 for(const change of MS_ADOPTED_COPY_SUCCESSORS){
  assert.equal(current.entries.filter(entry=>entry.id===change.after.id).length,1,'Unique declared MS successor '+change.after.id);
  assert.deepEqual(current.entries[change.index],change.after,'Exact accepted MS successor/index '+change.after.id);
  predecessor.entries[change.index]=structuredClone(change.before);
 }
 assert.deepEqual(current.msTimingDatedSuffix,MS_ADOPTED_COPY_DATED_SUFFIX,'Exact accepted MS dated suffix metadata');
 delete predecessor.msTimingDatedSuffix;
 return predecessor;
}
